/* 임시 */

.category_tabpanel_wrap .board_category {
  padding: 24px 28px;
  border-radius: 0px 0px 8px 8px;
  border: 1px solid #555;
  border-top: 0;
  font-size: 0;
}

.category_tabpanel_wrap .brd_category_item {
  display: inline-block;
  position: relative;
  padding: 0 24px;
  font-size: 16px;
  color: #626262;
}
.category_tabpanel_wrap .brd_category_item.is_selected {
/* 	background-color : #c15700;  */
/*     color: #fff; */
/*웹 접근성 수정*/
	color: #c15700;
	text-decoration: underline;
}
.category_tabpanel_wrap .brd_category_item.is_selected:after{
	content: "선택됨";
	position: absolute;
	width: 0;
	height: 0;
	overflow: hidden;
	color: transparent;
	display: block;
}
.category_tabpanel_wrap .brd_category_item:before {
  position: absolute;
  top: 50%;
  right: 0;
  width: 2px;
  height: 2px;
  background: #dedede;
  -ms-transform: translateY(-50%);
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
  content: '';
}
.category_tabpanel_wrap .brd_category_item:last-child:before {
  display: none;
}

